dtsPropsFor.Tabs:
tabs: { id: string; label: string }[];
active: string;
onChange: (id: string) => void;

dtsPropsFor.FilterTabs:
tabs: { id: string; label: string; /** Shown as a muted count after the label. Omit for a tab with no meaningful count. */ count?: number }[];
active: string;
onChange: (id: string) => void;

dtsPropsFor.DetailPanel:
title: React.ReactNode;
onClose: () => void;
onPrev?: () => void;
onNext?: () => void;
/** Pass tabs + activeTab + onTabChange together to show a tab bar under the header. */
tabs?: { id: string; label: string }[];
activeTab?: string;
onTabChange?: (id: string) => void;
/** Extra controls in the header row, e.g. an active/inactive badge. */
headerExtra?: React.ReactNode;
/** A persistent bar below the scroll area, e.g. the product slide-over's Save/Revert. */
footer?: React.ReactNode;
children: React.ReactNode;

dtsPropsFor.SegmentedControl:
options: { value: string; label: string }[];
value: string;
onChange: (value: string) => void;
ariaLabel?: string;

dtsPropsFor.CreatableSelect:
options: { id: number; name: string }[];
value: string;
onChange: (name: string) => void;
/** Called on blur with the matched option's id, or null when the typed name is new. */
onResolved: (id: number | null) => void;
placeholder?: string;
className?: string;

dtsPropsFor.StockCountFields:
/** null = inherit from the item's group / shop default. */
abcClass: "A" | "B" | "C" | null;
/** Kept as a string because it's bound to a free-text number input; "" means no override. */
intervalDays: string;
/** What the overrides currently resolve to (from the server). null hides the summary. */
classification: {
  abc_class: "A" | "B" | "C";
  interval_days: number;
  class_source: "item" | "group" | "default";
  interval_source: "item" | "tier" | "default";
  last_stock_take_at: string | null;
  next_due_at: string | null;
  /** null means never counted. */
  days_overdue: number | null;
  is_due: boolean;
} | null;
/** What the middle level is called for this item — "the Packaging category" — so an inherited value can name its source. */
groupLabel: string | null;
onAbcClassChange: (next: "A" | "B" | "C" | null) => void;
onIntervalDaysChange: (next: string) => void;
/** "rows" = labelled stacked rows (materials Counting tab); "inline" = compact two-input block. */
layout?: "inline" | "rows";
/** The item's line on the currently-open stock take, if any. Rows layout only. */
openTake?: { id: number; status: string } | null;
